INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM219NSE3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A factory has two machines, X and Y, that produce the same part. Machine X produces 60% of all parts, and Machine Y produces the remaining 40%. Of the parts produced by Machine X, 5% are defective. Of the parts produced by Machine Y, 10% are defective. A part is selected at random from the factory''s output and found to be defective. What is the probability that the part was produced by Machine Y?', NULL, '[{"key":"A","text":"$0.10$"},{"key":"B","text":"$0.40$"},{"key":"C","text":"$\\\\frac{4}{7}$"},{"key":"D","text":"$\\\\frac{3}{7}$"}]'::jsonb, 'C', NULL, E'The correct answer is C. The overall probability a part is defective is $P(\\text{def}) = (0.6)(0.05) + (0.4)(0.10) = 0.03 + 0.04 = 0.07$. The probability the defective part came from Machine Y is $\\frac{(0.4)(0.10)}{0.07} = \\frac{0.04}{0.07} = \\frac{4}{7}$. Option A simply restates the defect rate of Machine Y (0.10) without conditioning on the part actually being defective. Option B ignores the defect information entirely and reports only the prior probability that a part came from Machine Y (0.40). Option D sets up the ratio correctly but attributes the numerator to the wrong machine, computing $\\frac{0.03}{0.07} = \\frac{3}{7}$, which is actually $P(\\text{Machine X} \\mid \\text{defective})$.', '{"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21E4LLY', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $3(2x + 4) - 2x$?', NULL, '[{"key":"A","text":"$4x + 12$"},{"key":"B","text":"$4x + 4$"},{"key":"C","text":"$8x + 12$"},{"key":"D","text":"$4x + 10$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Distribute the 3 across the parentheses: $3(2x+4) = 6x + 12$. Then combine like terms with $-2x$: $6x + 12 - 2x = 4x + 12$. Option B results from distributing the 3 only to the $2x$ term and not to the $4$, giving $6x + 4 - 2x = 4x + 4$. Option C results from treating $-2x$ as $+2x$, giving $6x + 12 + 2x = 8x + 12$. Option D results from a constant arithmetic error when combining terms.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22E0UOB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 - 9 = 0$?', NULL, '[{"key":"A","text":"$x = -3$ or $x = 3$"},{"key":"B","text":"$x = -9$ or $x = 9$"},{"key":"C","text":"$x = 3$"},{"key":"D","text":"$x = 9$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Adding 9 to both sides gives $x^2 = 9$, and taking the square root of both sides gives $x = \\pm 3$. Option B results from failing to take the square root and instead treating $x^2=9$ as if $x=9$ directly (and its negative). Option C reports only the positive root, missing that $x=-3$ also satisfies the equation. Option D combines the same square-root omission with reporting only one value.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22GYGK3', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $g$ satisfies $g(-1) = 5$ and $g(3) = -7$. For what value of $x$ does $g(x) = 0$?', NULL, '[{"key":"A","text":"$\\\\frac{2}{3}$"},{"key":"B","text":"$-\\\\frac{2}{3}$"},{"key":"C","text":"$2$"},{"key":"D","text":"$-\\\\frac{8}{3}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The rate of change is $\\frac{-7 - 5}{3 - (-1)} = \\frac{-12}{4} = -3$, so $g(x) = 5 - 3(x + 1) = 2 - 3x$. Setting $g(x) = 0$ gives $2 - 3x = 0$, so $x = \\frac{2}{3}$. Option B results from a sign error when solving the final equation for $x$. Option C results from incomplete reasoning: solving $3x = 2$ but reporting the coefficient''s numerator, 2, instead of dividing to get $\\frac{2}{3}$. Option D results from an equation setup error that uses the rate of change with the wrong sign, giving $g(x) = 3x + 8$ and solving $3x = -8$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 115, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22TUW81', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular prism has length $5$, width $4$, and height $3$. What is its volume?', NULL, '[{"key":"A","text":"$12$"},{"key":"B","text":"$20$"},{"key":"C","text":"$60$"},{"key":"D","text":"$75$"}]'::jsonb, 'C', NULL, E'The correct answer is C. The volume of a rectangular prism is $V = \\ell \\times w \\times h = 5 \\times 4 \\times 3 = 60$. Option A ($12$) results from adding the three dimensions ($5+4+3$) instead of multiplying them. Option B ($20$) results from multiplying only the length and width ($5 \\times 4$) and omitting the height. Option D ($75$) results from an arithmetic slip while multiplying $5 \\times 4 \\times 3$.', '{"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM232WBJS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has equation $x^2 + y^2 - 6x + 8y = 0$. What is the radius of the circle?', NULL, '[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$10$"},{"key":"D","text":"$25$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Completing the square: $(x^2 - 6x + 9) + (y^2 + 8y + 16) = 9 + 16$, so $(x-3)^2 + (y+4)^2 = 25$. This is a circle with radius $r = \\sqrt{25} = 5$. Option D ($25$) stops at $r^2 = 25$ without taking the square root to find $r$. Option C ($10$) confuses the radius with the diameter. Option B ($7$) results from incorrectly adding $\\sqrt{9} + \\sqrt{16} = 3 + 4 = 7$ instead of computing $\\sqrt{9+16}$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 80, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM239UMU4', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $\\begin{cases} 6x - 9y = 15 \\\\ 4x + ky = 8 \\end{cases}$ has no solution. What is the value of $k$?', NULL, '[{"key":"A","text":"$-6$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$4$"},{"key":"D","text":"$6$"}]'::jsonb, 'A', NULL, E'The correct answer is A. A system of two linear equations has no solution when the lines are parallel but not identical: the ratio of $x$-coefficients must equal the ratio of $y$-coefficients while the ratio of constants differs. Setting $\\frac{6}{4} = \\frac{-9}{k}$ gives $6k = -36$, so $k = -6$. Checking the constants: with $k = -6$, the equations reduce to $2x - 3y = 5$ and $2x - 3y = 4$, which have the same slope but different intercepts, confirming no solution. Option B ($-4$) and Option C ($4$) are sign-error variants of solving the coefficient proportion incorrectly; substituting either value produces a system with a different slope in the second equation, which intersects the first equation at exactly one point rather than producing no solution. Option D ($6$) reflects a conceptual error of matching $k$ directly to the positive $x$-coefficient ratio without accounting for the sign of the $y$-term, and also yields a system with a unique solution rather than no solution.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 100, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
