INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26DQWW4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'Solve for $x$: $2(x - 3) + 5 = 3x - 4$.', NULL, '[{"key":"A","text":"$3$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$1$"},{"key":"D","text":"$-1$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Distribute the 2 on the left side: $2x - 6 + 5 = 3x - 4$, which simplifies to $2x - 1 = 3x - 4$. Adding 4 and subtracting $2x$ from both sides gives $3 = x$. Option B results from a sign error when combining $-6 + 5$. Option C comes from forgetting to distribute the 2 across both terms in $(x - 3)$, effectively solving $2x - 3 + 5 = 3x - 4$. Option D results from an arithmetic slip when moving terms across the equal sign.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26KP0CD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $ABC$, the measure of angle $A$ is $x°$ and the measure of angle $B$ is $2x°$. The exterior angle at vertex $C$, adjacent to $\\angle ACB$, measures $126°$. What is the value of $x$?', NULL, '[{"key":"A","text":"$18$"},{"key":"B","text":"$42$"},{"key":"C","text":"$63$"},{"key":"D","text":"$84$"}]'::jsonb, 'B', NULL, E'The correct answer is B. By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two remote (non-adjacent) interior angles. Here, that gives $x + 2x = 126$, so $3x = 126$ and $x = 42$. Option A ($18$) comes from incorrectly treating $126°$ as a third interior angle, setting up $x + 2x + 126 = 180$ instead of using the exterior angle relationship. Option C ($63$) comes from ignoring the coefficient on angle $B$ and solving $x + x = 126$. Option D ($84$) results from an arithmetic slip that scales $126$ by $\\frac{2}{3}$ instead of dividing by $3$.', '{"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26NUBYJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In a triangle, two of the interior angles measure $50°$ and $70°$. What is the measure, in degrees, of the third angle?', NULL, '[{"key":"A","text":"$60°$"},{"key":"B","text":"$110°$"},{"key":"C","text":"$120°$"},{"key":"D","text":"$130°$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The interior angles of a triangle sum to $180°$, so the third angle is $180° - 50° - 70° = 60°$. Option B ($110°$) results from subtracting only the $70°$ angle from $180°$ and ignoring the $50°$ angle. Option D ($130°$) results from subtracting only the $50°$ angle from $180°$ and ignoring the $70°$ angle. Option C ($120°$) comes from adding the two given angles together, which confuses the sum of the remote interior angles (an exterior angle relationship) with the measure of the third interior angle itself.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26WJ192', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{x^2 - 9}{x + 3}$ for $x \\neq -3$?', NULL, '[{"key":"A","text":"$x - 3$"},{"key":"B","text":"$x + 3$"},{"key":"C","text":"$x^2 - 3$"},{"key":"D","text":"$\\\\frac{x-3}{2}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The numerator is a difference of squares: $x^2 - 9 = (x-3)(x+3)$. Dividing by $(x+3)$ leaves $x - 3$. Option B results from a sign error when factoring the difference of squares. Option C results from only partially reducing the expression, leaving the squared term while dropping just the denominator''s effect on the constant. Option D introduces an extra factor of 2 that has no basis in the original expression. Checking $x=2$: the original expression equals $\\frac{4-9}{5} = -1$, which matches $x-3=-1$ but not the other options.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27RIS45', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'The two-way table shows the results of a survey of 200 students about whether they participate in a sport and whether they participate in a music program.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27U8AAV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher models the relationship between a car''s age, in years, and its resale value, in dollars, using the equation $v = 25{,}000 - 1{,}200a$, where $a$ is the car''s age and $v$ is its resale value. Based on this model, what does the value $1{,}200$ represent?', NULL, '[{"key":"A","text":"The car''s value, in dollars, when it is new"},{"key":"B","text":"The amount, in dollars, that the car''s resale value decreases each year"},{"key":"C","text":"The car''s age, in years, when it has no value"},{"key":"D","text":"The total decrease in the car''s value, in dollars, over its entire lifetime"}]'::jsonb, 'B', NULL, E'The correct answer is B. In the linear model $v = 25{,}000 - 1{,}200a$, the coefficient $1{,}200$ is the slope, which represents the constant rate of change in resale value per year of age — a decrease of $\\$1{,}200$ each year. Option A confuses the slope with the $y$-intercept, $25{,}000$, which is the value of the car when $a = 0$. Option C confuses the slope with the $x$-intercept, the age at which $v = 0$. Option D misinterprets the annual rate of change as a fixed lifetime total, but the model gives a per-year rate, not a one-time total.', '{"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 80, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM291T22L', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $k$ is perpendicular to the line $3x - 4y = 8$ and passes through the point $(-2, 5)$. What is the $y$-intercept of line $k$?', NULL, '[{"key":"A","text":"$\\\\frac{7}{3}$"},{"key":"B","text":"$-\\\\frac{7}{3}$"},{"key":"C","text":"$\\\\frac{3}{4}$"},{"key":"D","text":"$\\\\frac{23}{3}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Rewriting $3x - 4y = 8$ in slope-intercept form gives $y = \\frac{3}{4}x - 2$, so its slope is $\\frac{3}{4}$. A perpendicular line has slope $-\\frac{4}{3}$. Using point-slope form: $y - 5 = -\\frac{4}{3}(x + 2)$, which simplifies to $y = -\\frac{4}{3}x + \\frac{7}{3}$, giving a $y$-intercept of $\\frac{7}{3}$. Option B results from an arithmetic slip when combining $-\\frac{8}{3}$ and $5$. Option C results from a conceptual gap: using the original line''s slope instead of taking the negative reciprocal. Option D results from a sign error that uses slope $\\frac{4}{3}$ instead of $-\\frac{4}{3}$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29ZLQXS', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What is the largest integer value of $x$ that satisfies the inequality $3x + 4 \\leq 19$?', NULL, '[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$15$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Subtract 4 from both sides of $3x + 4 \\leq 19$ to get $3x \\leq 15$, then divide by 3 to get $x \\leq 5$. The largest integer satisfying this is 5. Option B ($6$) comes from an arithmetic slip computing $15/3 = 6$ instead of $5$. Option C ($7$) results from an equation setup error that adds 4 to 19 instead of subtracting, yielding $3x \\leq 23$ and $x \\leq 7.67$, rounded down to 7. Option D ($15$) reflects incomplete reasoning that stops after isolating $3x \\leq 15$ without dividing by 3.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B2LE4X', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'The solution to the inequality $|2x - 5| \\leq 9$ can be written as $a \\leq x \\leq b$. What is the value of $b - a$?', NULL, '[{"key":"A","text":"$4.5$"},{"key":"B","text":"$9$"},{"key":"C","text":"$14$"},{"key":"D","text":"$18$"}]'::jsonb, 'B', NULL, E'The correct answer is B. The inequality $|2x - 5| \\leq 9$ splits into $-9 \\leq 2x - 5 \\leq 9$. Adding 5 across all parts gives $-4 \\leq 2x \\leq 14$, and dividing by 2 gives $-2 \\leq x \\leq 7$, so $a = -2$ and $b = 7$, giving $b - a = 9$. Option A ($4.5$) results from incomplete reasoning that divides the final difference $9$ by 2 again instead of stopping at the correct bounds. Option C ($14$) misreads the question, reporting the value of the upper bound of $2x$ ($14$) instead of computing $b - a$. Option D ($18$) comes from an arithmetic slip that forgets to divide $-4 \\leq 2x \\leq 14$ by 2, treating $14 - (-4) = 18$ as the final difference.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BHBFSA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A car travels at a constant speed of $60$ miles per hour. How many miles does it travel in $3$ hours?', NULL, '[{"key":"A","text":"$20$"},{"key":"B","text":"$57$"},{"key":"C","text":"$63$"},{"key":"D","text":"$180$"}]'::jsonb, 'D', NULL, E'The correct answer is D. Distance equals rate times time, so the car travels $60 \\times 3 = 180$ miles. Option A ($20$) results from dividing $60$ by $3$ instead of multiplying. Option B ($57$) results from subtracting $3$ from $60$ instead of multiplying. Option C ($63$) results from adding $3$ to $60$ instead of multiplying.', '{"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CMYR5U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains 5 red marbles, 3 blue marbles, and 2 green marbles. One marble is selected at random from the bag. What is the probability that the marble is blue?', NULL, '[{"key":"A","text":"$\\\\frac{1}{10}$"},{"key":"B","text":"$\\\\frac{3}{10}$"},{"key":"C","text":"$\\\\frac{1}{3}$"},{"key":"D","text":"$\\\\frac{1}{2}$"}]'::jsonb, 'B', NULL, E'The correct answer is B. There are $5 + 3 + 2 = 10$ marbles total, and 3 of them are blue, so the probability of selecting a blue marble is $\\frac{3}{10}$. Option A results from dividing 1 instead of 3 by 10. Option C incorrectly divides the number of blue marbles by the number of color categories (3) instead of the total number of marbles. Option D incorrectly assumes there are only two equally likely outcomes.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D3UY34', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line passes through the points $(1, -2)$ and $(5, k)$ and is parallel to the line $5x - 2y = 10$. What is the value of $k$?', NULL, '[{"key":"A","text":"$-\\\\frac{2}{5}$"},{"key":"B","text":"$8$"},{"key":"C","text":"$9$"},{"key":"D","text":"$12$"}]'::jsonb, 'B', NULL, E'The correct answer is B. Rewriting $5x - 2y = 10$ gives $y = \\frac{5}{2}x - 5$, so parallel lines have slope $\\frac{5}{2}$. Setting the slope between the two points equal to $\\frac{5}{2}$: $\\frac{k - (-2)}{5 - 1} = \\frac{5}{2}$, so $\\frac{k + 2}{4} = \\frac{5}{2}$, giving $k + 2 = 10$ and $k = 8$. Option A results from a conceptual gap: using the reciprocal slope $\\frac{2}{5}$ instead of $\\frac{5}{2}$. Option C results from an arithmetic slip when cross-multiplying, multiplying only the $k$ term by 2 instead of the whole expression $(k+2)$. Option D results from a sign error that treats the numerator as $k - 2$ instead of $k + 2$.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 115, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D5JHG3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'In a poll of a random sample of 600 adults in City A, 52% support a new transportation policy, with a margin of error of $\\pm 4$ percentage points at the 95% confidence level. In a separate poll of a random sample of 550 adults in City B, 47% support the same policy, with a margin of error of $\\pm 4$ percentage points at the 95% confidence level. Based on these results, which conclusion is best supported?', NULL, '[{"key":"A","text":"It cannot be concluded that a greater proportion of adults in City A support the policy than in City B, because the two confidence intervals overlap."},{"key":"B","text":"A greater proportion of adults in City A support the policy than in City B, because $52\\\\%$ is greater than $47\\\\%$."},{"key":"C","text":"It cannot be concluded that a greater proportion of adults in City A support the policy than in City B, because the two confidence intervals do not overlap."},{"key":"D","text":"A greater proportion of adults in City B support the policy than in City A, because City B''s interval extends up to $51\\\\%$."}]'::jsonb, 'A', NULL, E'The correct answer is A. City A''s confidence interval is $48\\%$ to $56\\%$, and City B''s confidence interval is $43\\%$ to $51\\%$. Since these intervals overlap (both contain values between $48\\%$ and $51\\%$), the difference between the sample percentages could plausibly be due to sampling variability rather than a true difference in the populations, so no definitive comparison can be made. Option B ignores the margin of error entirely and treats the raw sample percentages as if they were exact population values. Option C miscalculates the intervals and incorrectly claims they do not overlap. Option D correctly notes City B''s upper bound but misreads the comparison, drawing a conclusion in the wrong direction from overlapping intervals that support no conclusion at all.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 85, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D92EI5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'For $9$ employees at a company, the mean salary is $\\$52{,}000$. A tenth employee is hired at a salary of $\\$150{,}000$, far higher than any current salary. Which statement is best supported about the effect of adding this salary on the mean and median salary of the $10$ employees?', NULL, '[{"key":"A","text":"Both the mean and median will increase by the same amount."},{"key":"B","text":"The mean will increase substantially, while the median will increase little, if at all."},{"key":"C","text":"The median will increase substantially, while the mean will remain unchanged."},{"key":"D","text":"Neither the mean nor the median will be affected by adding the new salary."}]'::jsonb, 'B', NULL, E'The correct answer is B. The original total salary is $9 \\times 52{,}000 = \\$468{,}000$; adding $\\$150{,}000$ gives a new total of $\\$618{,}000$ over $10$ employees, a new mean of $\\$61{,}800$, an increase of $\\$9{,}800$. The median, however, is determined by the middle-ranked values, and adding one extreme outlier shifts the ordering by at most one position, so the median changes little or not at all. This shows the mean is far more sensitive to outliers than the median. Option A incorrectly assumes both measures respond equally to an outlier. Option C reverses which measure is resistant to outliers. Option D ignores that adding a new data point necessarily changes the total and therefore the mean.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DZLR93', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, the measure of angle $A$ is $10°$ more than twice the measure of angle $B$, and the measure of angle $C$ is $10°$ less than three times the measure of angle $B$. What is the measure of angle $A$, in degrees?', NULL, '[{"key":"A","text":"$30$"},{"key":"B","text":"$60$"},{"key":"C","text":"$70$"},{"key":"D","text":"$80$"}]'::jsonb, 'C', NULL, E'The correct answer is C. Let angle $B = x$. Then angle $A = 2x + 10$ and angle $C = 3x - 10$. Since the angles of a triangle sum to $180°$: $(2x+10) + x + (3x-10) = 180$, which simplifies to $6x = 180$, so $x = 30$. Therefore angle $A = 2(30) + 10 = 70°$. Option A ($30$) is the measure of angle $B$, not angle $A$ — the question asks specifically for angle $A$. Option D ($80$) is the measure of angle $C$, not angle $A$. Option B ($60$) results from an arithmetic slip in computing $2(30)$ as $50$ instead of $60$, giving $50+10=60$.', '{"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 100, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F1AAPW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'Circle $O$ has a radius of $12$. Chord $\\overline{AB}$ subtends a central angle of $120°$. What is the length of $\\overline{AB}$?', NULL, '[{"key":"A","text":"$6\\\\sqrt{3}$"},{"key":"B","text":"$12$"},{"key":"C","text":"$12\\\\sqrt{3}$"},{"key":"D","text":"$24$"}]'::jsonb, 'C', NULL, E'The correct answer is C. Triangle $OAB$ is isosceles with $OA = OB = 12$ and apex angle $120°$ at $O$, so each base angle is $30°$. Dropping a perpendicular from $O$ to $\\overline{AB}$ bisects both the angle and the chord, giving half of $AB$ equal to $12\\sin(60°) = 6\\sqrt{3}$, so $AB = 12\\sqrt{3}$. Option A ($6\\sqrt{3}$) is only half the chord length — the bisected segment was never doubled. Option B ($12$) incorrectly assumes the chord length equals the radius. Option D ($24$) incorrectly assumes the chord equals the diameter, which would only be true for a $180°$ central angle.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F6OG7L', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A gym charges a one-time membership fee plus a fixed monthly rate. A member who stayed for 4 months paid a total of $\\$180$, and a member who stayed for 9 months paid a total of $\\$305$. What is the monthly rate, in dollars?', NULL, '[{"key":"A","text":"$\\\\$20$"},{"key":"B","text":"$\\\\$25$"},{"key":"C","text":"$\\\\$30$"},{"key":"D","text":"$\\\\$45$"}]'::jsonb, 'B', NULL, E'The correct answer is B. Let $f$ be the one-time fee and $r$ be the monthly rate, so $f + 4r = 180$ and $f + 9r = 305$. Subtracting the first equation from the second eliminates $f$: $5r = 125$, so $r = 25$. Option A ($\\$20$) results from an arithmetic slip dividing $125$ by an incorrect difference of 6 months instead of 5. Option C ($\\$30$) comes from an equation setup error that subtracts the equations in the wrong order and misreads the resulting constant as $150$ instead of $125$. Option D ($\\$45$) is the one-time fee $f$ found by back-substitution, mistakenly reported instead of the monthly rate $r$.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 80, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G5TLFP', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $\\frac{4x^2 - 25}{2x^2 + x - 15}$ for values of $x$ where the expression is defined?', NULL, '[{"key":"A","text":"$\\\\frac{2x+5}{x+3}$"},{"key":"B","text":"$\\\\frac{2x-5}{x+3}$"},{"key":"C","text":"$2x + 5$"},{"key":"D","text":"$\\\\frac{4x-25}{2x-15}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The numerator factors as a difference of squares: $4x^2-25=(2x-5)(2x+5)$. The denominator factors as $2x^2+x-15=(2x-5)(x+3)$, since $(2x-5)(x+3)=2x^2+6x-5x-15=2x^2+x-15$. Canceling the common factor $(2x-5)$ leaves $\\frac{2x+5}{x+3}$. Option B keeps the wrong sign on the numerator factor. Option C drops the denominator after canceling, as if the whole denominator were also a common factor. Option D results from canceling the $x^2$ terms directly without factoring, which is not a valid operation; checking $x=1$ shows this option gives $\\frac{-21}{-13} \\approx 1.615$, while the correct expression gives $\\frac{7}{4}=1.75$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GBNLS8', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'Solve for $x$: $3x + 7 = 22$.', NULL, '[{"key":"A","text":"$5$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$\\\\frac{29}{3}$"},{"key":"D","text":"$15$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Subtract 7 from both sides of $3x + 7 = 22$ to get $3x = 15$, then divide by 3 to get $x = 5$. Option B results from a sign error when isolating $x$. Option C comes from adding 22 and 7 instead of subtracting, giving $3x = 29$. Option D is the value of $3x$ after subtracting 7, but the student forgot to divide by 3.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GBRMRY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to investigate whether a two-day-per-week work-from-home policy increases job satisfaction among all employees of a large city government. From a list of employees working only in the City Hall building (one of many city government buildings), researchers randomly selected 150 employees and randomly assigned them to either the new policy or the standard policy, then measured job satisfaction after three months. The results showed a statistically significant increase in job satisfaction for those under the new policy. Which of the following is the most appropriate conclusion?', NULL, '[{"key":"A","text":"The results support a causal conclusion that the policy increases job satisfaction for employees like those in City Hall, but this should not be generalized to all city government employees, since the sample was drawn only from City Hall employees."},{"key":"B","text":"The results support a causal conclusion that the policy increases job satisfaction for all city government employees, since the difference was statistically significant."},{"key":"C","text":"No causal conclusion can be drawn at all, because employees were not surveyed about their own department."},{"key":"D","text":"The result cannot be trusted because a sample of 150 employees is too small to detect a statistically significant difference."}]'::jsonb, 'A', NULL, E'The correct answer is A. Because employees were randomly assigned to the policy or standard conditions, a causal conclusion is justified. However, the sample was drawn only from City Hall employees, not from all city government employees, so the finding can only be generalized to a population like the one sampled, not to the entire city workforce across all buildings and departments. Option B correctly notes the causal validity from random assignment but incorrectly extends the conclusion beyond the sampled population. Option C misreads the study design: departmental self-report was never the issue, and random assignment was already used, so a causal claim can be made for the sampled population. Option D misapplies a sample-size concern after significance has already been established statistically, and 150 is a reasonable size for detecting a real effect; the actual limitation is about the scope of the sampling frame, not the sample size.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 85, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GW49Z5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'Data Set A has a standard deviation of $3$, and Data Set B has a standard deviation of $8$. Both data sets have the same mean. Which statement is best supported by this information?', NULL, '[{"key":"A","text":"The values in Data Set A are, on average, farther from the mean than the values in Data Set B."},{"key":"B","text":"The values in Data Set B are, on average, farther from the mean than the values in Data Set A."},{"key":"C","text":"Data Set A must have a greater range than Data Set B."},{"key":"D","text":"Data Set A and Data Set B have the same level of variability."}]'::jsonb, 'B', NULL, E'The correct answer is B. Standard deviation measures how far, on average, the values in a data set are spread from the mean; a larger standard deviation means greater spread. Since Data Set B''s standard deviation ($8$) is greater than Data Set A''s ($3$), Data Set B''s values are farther from the mean on average. Option A reverses this relationship. Option C incorrectly assumes that a smaller standard deviation guarantees a greater range, which is not necessarily true since range depends only on the two extreme values. Option D misinterprets equal means as implying equal variability, ignoring the differing standard deviations.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GWQG5P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $6$ and $8$. What is the length of the hypotenuse?', NULL, '[{"key":"A","text":"$7$"},{"key":"B","text":"$10$"},{"key":"C","text":"$14$"},{"key":"D","text":"$48$"}]'::jsonb, 'B', NULL, E'The correct answer is B. By the Pythagorean theorem, the hypotenuse $c$ satisfies $c^2 = 6^2 + 8^2 = 36 + 64 = 100$, so $c = 10$. Option C ($14$) results from simply adding the two legs ($6+8$) instead of applying the Pythagorean theorem. Option A ($7$) results from averaging the two legs, which has no geometric basis for finding the hypotenuse. Option D ($48$) comes from computing the area of the triangle''s legs product ($6 \\times 8$) rather than the hypotenuse length.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IKS8N5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $9$. What is the circumference of the circle, in terms of $\\pi$?', NULL, '[{"key":"A","text":"$9\\\\pi$"},{"key":"B","text":"$18\\\\pi$"},{"key":"C","text":"$36\\\\pi$"},{"key":"D","text":"$81\\\\pi$"}]'::jsonb, 'B', NULL, E'The correct answer is B. Circumference is given by $C = 2\\pi r = 2\\pi(9) = 18\\pi$. Option A ($9\\pi$) results from computing $\\pi r$ and omitting the factor of $2$ in the circumference formula. Option D ($81\\pi$) results from confusing the circumference formula with the area formula $\\pi r^2 = \\pi(9)^2 = 81\\pi$. Option C ($36\\pi$) results from an arithmetic slip that doubles the radius twice instead of once.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J2HD7B', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the sum of the solutions to $x^2 - 5x + 6 = 0$?', NULL, '[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$1$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Factoring $x^2-5x+6=0$ gives $(x-2)(x-3)=0$, so the solutions are $x=2$ and $x=3$, which sum to $5$. Option B is the product of the solutions ($2 \\times 3 = 6$), not their sum. Option C results from a sign error, taking the sum as $-5$ instead of $5$. Option D is the difference between the solutions ($3-2=1$), not their sum.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JEXTTW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 500 registered voters found that 54% support a proposed ballot measure, with a margin of error of $\\pm 3$ percentage points. Based on this survey, which of the following is the best estimate of the range of the percentage of all registered voters who support the measure?', NULL, '[{"key":"A","text":"$51\\\\%$ to $57\\\\%$"},{"key":"B","text":"$54\\\\%$ to $60\\\\%$"},{"key":"C","text":"$48\\\\%$ to $54\\\\%$"},{"key":"D","text":"$51\\\\%$ to $60\\\\%$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The margin of error is applied both above and below the sample estimate: $54\\% - 3\\% = 51\\%$ and $54\\% + 3\\%=57\\%$, giving the interval $51\\%$ to $57\\%$. Option B incorrectly adds the margin of error twice instead of both adding and subtracting it, giving an upper bound of $60\\%$ while keeping the lower bound at the estimate itself. Option C incorrectly subtracts the margin of error twice instead of both adding and subtracting it. Option D mixes a correctly subtracted lower bound with an incorrectly doubled upper bound.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JG45Z1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'Pump A alone can fill a tank in $4$ hours, and Pump B alone can fill the same tank in $6$ hours. If both pumps work together at their constant individual rates, how many hours will it take them to fill the tank?', NULL, '[{"key":"A","text":"$\\\\frac{5}{12}$"},{"key":"B","text":"$2.4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$10$"}]'::jsonb, 'B', NULL, E'The correct answer is B. Pump A''s rate is $\\frac{1}{4}$ tank per hour and Pump B''s rate is $\\frac{1}{6}$ tank per hour, so the combined rate is $\\frac{1}{4} + \\frac{1}{6} = \\frac{5}{12}$ tank per hour. The time to fill one tank is the reciprocal, $\\frac{12}{5} = 2.4$ hours. Option A ($\\frac{5}{12}$) gives the combined rate itself but forgets to take its reciprocal to find the time. Option C ($5$) incorrectly averages the two individual times, $\\frac{4+6}{2}$, instead of combining the rates. Option D ($10$) incorrectly adds the two individual times together.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JWNGMF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The graph of $f(x) = (x-3)^2 + 5$ is a parabola in the xy-plane. What is the vertex of the graph?', NULL, '[{"key":"A","text":"$(3, 5)$"},{"key":"B","text":"$(-3, 5)$"},{"key":"C","text":"$(3, -5)$"},{"key":"D","text":"$(5, 3)$"}]'::jsonb, 'A', NULL, E'The correct answer is A. For a parabola written in vertex form $f(x) = (x-h)^2 + k$, the vertex is $(h,k)$. Here $h=3$ and $k=5$, so the vertex is $(3,5)$. Option B results from a sign error on the $h$-coordinate, reading $x-3$ as if it were $x+3$. Option C results from a sign error on the $k$-coordinate. Option D swaps the coordinates, misreading which value corresponds to $x$ and which to $y$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JZA9NA', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $y$ in the solution to the system $\\begin{cases} x + y = 7 \\\\ x - y = 3 \\end{cases}$?', NULL, '[{"key":"A","text":"$2$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$10$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Adding the two equations eliminates $y$: $2x = 10$, so $x = 5$. Substituting into $x + y = 7$ gives $y = 2$. Option B ($4$) results from misreading the question and reporting $x - y = 3$''s leftover value pattern instead of correctly solving for $y$. Option C ($5$) is the value of $x$, mistakenly reported instead of $y$ because the student stopped after finding $x$. Option D ($10$) comes from an equation setup error that reports $2x = 10$ from adding the equations as the final answer without dividing or substituting to find $y$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KG1T2G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of $5$ students on a chess team are $12, 14, 13, 15,$ and $20$. What is the mean age of the students?', NULL, '[{"key":"A","text":"$12$"},{"key":"B","text":"$14$"},{"key":"C","text":"$14.8$"},{"key":"D","text":"$74$"}]'::jsonb, 'C', NULL, E'The correct answer is C. The sum of the ages is $12+14+13+15+20 = 74$, and dividing by the $5$ students gives a mean of $74 \\div 5 = 14.8$. Option A ($12$) is simply the minimum value in the list, not the mean. Option B ($14$) is the median of the sorted list, not the mean. Option D ($74$) is the sum of the ages, but it was never divided by the number of students.', '{"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NB4U8C', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $ABC$, the right angle is at $C$. The altitude from $C$ to the hypotenuse $\\overline{AB}$ meets $\\overline{AB}$ at point $D$, dividing it into segments $AD = 4$ and $DB = 9$. What is the length of $\\overline{CD}$?', NULL, '[{"key":"A","text":"$6$"},{"key":"B","text":"$6.5$"},{"key":"C","text":"$13$"},{"key":"D","text":"$36$"}]'::jsonb, 'A', NULL, E'The correct answer is A. When an altitude is drawn from the right angle to the hypotenuse, the altitude''s length is the geometric mean of the two segments it creates: $CD^2 = AD \\times DB = 4 \\times 9 = 36$, so $CD = 6$. Option D ($36$) is the value of $CD^2$ — the correct relationship was set up but the square root was never taken. Option B ($6.5$) incorrectly uses the arithmetic mean of $4$ and $9$ instead of the geometric mean. Option C ($13$) results from simply adding $AD + DB$ rather than applying the geometric mean relation.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NNKZEF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between hours studied, $x$, and exam score, $y$, for a group of students. The line of best fit is $y = 4x + 50$. According to this model, what is the predicted exam score for a student who studies $10$ hours?', NULL, '[{"key":"A","text":"$40$"},{"key":"B","text":"$90$"},{"key":"C","text":"$96$"},{"key":"D","text":"$240$"}]'::jsonb, 'B', NULL, E'The correct answer is B. Substituting $x = 10$ into the model gives $y = 4(10) + 50 = 40 + 50 = 90$. Option A ($40$) computes $4 \\times 10$ but forgets to add the intercept of $50$. Option C ($96$) makes an arithmetic error while adding $40$ and $50$. Option D ($240$) incorrectly computes $4 \\times (10+50)$ instead of $4 \\times 10 + 50$, misapplying the order of operations.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OB2SR9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The graph of $g$ is obtained by taking the graph of $f(x) = x^2$, shifting it right 4 units and up 2 units, and then reflecting the result over the x-axis. Which equation defines $g(x)$?', NULL, '[{"key":"A","text":"$g(x) = -(x-4)^2 - 2$"},{"key":"B","text":"$g(x) = -(x-4)^2 + 2$"},{"key":"C","text":"$g(x) = (x-4)^2 - 2$"},{"key":"D","text":"$g(x) = -(x+4)^2 - 2$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Shifting $f(x)=x^2$ right 4 and up 2 gives $(x-4)^2 + 2$. Reflecting the entire function over the x-axis multiplies the whole expression by $-1$: $g(x) = -\\left[(x-4)^2+2\\right] = -(x-4)^2 - 2$. Option B reflects only the squared term and fails to distribute the negative sign to the constant term. Option C omits the reflection entirely. Option D uses the wrong sign for the horizontal shift, moving the graph left instead of right.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PA4WDF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher polls a random sample of 400 people and obtains a margin of error of $\\pm 5$ percentage points at a given confidence level. Assuming the underlying population proportion and confidence level stay the same, and that margin of error is inversely proportional to the square root of the sample size, by approximately what factor must the sample size be increased to reduce the margin of error to approximately $\\pm 2.5$ percentage points?', NULL, '[{"key":"A","text":"$2$"},{"key":"B","text":"$4$"},{"key":"C","text":"$8$"},{"key":"D","text":"$16$"}]'::jsonb, 'B', NULL, E'The correct answer is B. Margin of error is proportional to $\\frac{1}{\\sqrt{n}}$, so to cut the margin of error in half (from $\\pm 5$ to $\\pm 2.5$), the sample size $n$ must increase by a factor of $2^2 = 4$, since $\\frac{1}{\\sqrt{4n}} = \\frac{1}{2\\sqrt{n}}$. Option A incorrectly assumes margin of error is inversely proportional to $n$ directly (a linear relationship) rather than to $\\sqrt{n}$, so doubling the sample size seems sufficient. Option C results from an arithmetic slip combining the factor of 2 with an extra unnecessary multiplication. Option D incorrectly squares the target factor of 4 itself, misapplying the inverse-square-root relationship a second time.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 100, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QK4LPB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone has a volume of $270\\pi$ cubic units. A second cone is similar to the first, with all linear dimensions scaled by a factor of $\\frac{2}{3}$. What is the volume of the second cone, in cubic units?', NULL, '[{"key":"A","text":"$80\\\\pi$"},{"key":"B","text":"$120\\\\pi$"},{"key":"C","text":"$180\\\\pi$"},{"key":"D","text":"$405\\\\pi$"}]'::jsonb, 'A', NULL, E'The correct answer is A. When linear dimensions of a solid are scaled by a factor $k$, the volume scales by $k^3$. Here $k = \\frac{2}{3}$, so the volume scale factor is $\\left(\\frac{2}{3}\\right)^3 = \\frac{8}{27}$, giving a new volume of $270\\pi \\times \\frac{8}{27} = 80\\pi$. Option C ($180\\pi$) results from scaling the volume by the linear factor directly ($270\\pi \\times \\frac{2}{3}$) instead of cubing the scale factor. Option B ($120\\pi$) results from squaring the scale factor, $\\left(\\frac{2}{3}\\right)^2 = \\frac{4}{9}$, instead of cubing it. Option D ($405\\pi$) results from using the reciprocal scale factor $\\frac{3}{2}$ instead of $\\frac{2}{3}$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 115, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QR7R99', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer causes an increase in tomato plant growth. Which study design would best allow the researcher to make a valid causal claim about the fertilizer''s effect?', NULL, '[{"key":"A","text":"Randomly assign tomato plants to receive either the new fertilizer or no fertilizer, then compare the growth of the two groups."},{"key":"B","text":"Survey gardeners about which fertilizer they already use and record the growth of their plants."},{"key":"C","text":"Observe plants that different gardeners happened to treat with the fertilizer, without assigning who receives it."},{"key":"D","text":"Measure the growth of a single group of plants before and after applying the fertilizer, with no comparison group."}]'::jsonb, 'A', NULL, E'The correct answer is A. Random assignment of the fertilizer treatment creates comparable groups that differ systematically only in whether they received the fertilizer, so any difference in growth can be attributed to the fertilizer itself, supporting a causal claim. Option B is an observational study: gardeners chose their own fertilizer, so any relationship between fertilizer and growth could be explained by other differences among gardeners rather than the fertilizer. Option C is also observational, since there is no random assignment, so pre-existing differences between plants or growing conditions could explain any observed difference. Option D has no control group at all, so growth over time cannot be separated from the effect of the fertilizer.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 55, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QTXPBG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'After a $20\\%$ increase, the price of a book is $\\$54$. What was the original price of the book?', NULL, '[{"key":"A","text":"$\\\\$40.50$"},{"key":"B","text":"$\\\\$43.20$"},{"key":"C","text":"$\\\\$45$"},{"key":"D","text":"$\\\\$64.80$"}]'::jsonb, 'C', NULL, E'The correct answer is C. If $x$ is the original price, then $1.2x = 54$, so $x = 54 \\div 1.2 = \\$45$. Option A ($\\$40.50$) results from an error while dividing $54$ by $1.2$. Option B ($\\$43.20$) results from computing $54 \\times 0.8$, incorrectly treating the $20\\%$ as a direct decrease from $\\$54$ rather than reversing an increase. Option D ($\\$64.80$) results from applying another $20\\%$ increase to $\\$54$ instead of solving for the original price.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R7HUYR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A scatterplot of $x$ and $y$ shows a strong linear association modeled by the line of best fit $y = 2.5x + 10$. For a particular data point, $x = 20$ and the actual observed value is $y = 55$. What is the residual for this data point, and what does it indicate about the model''s prediction?', NULL, '[{"key":"A","text":"The residual is $-5$, indicating the actual value is below the value predicted by the model."},{"key":"B","text":"The residual is $5$, indicating the actual value is above the value predicted by the model."},{"key":"C","text":"The residual is $-5$, indicating the actual value is above the value predicted by the model."},{"key":"D","text":"The residual is $60$, indicating the model predicted a value of $60$ instead of $55$."}]'::jsonb, 'A', NULL, E'The correct answer is A. The model predicts $y = 2.5(20) + 10 = 60$. The residual is the observed value minus the predicted value: $55 - 60 = -5$. A negative residual means the actual observed value falls below the line, so the model overpredicted this data point. Option B reverses the sign of the residual, which would incorrectly indicate the observed value exceeds the prediction. Option C correctly computes the residual as $-5$ but misinterprets what a negative residual means, reversing the direction of the error. Option D reports the predicted value itself rather than the residual, and mislabels it as the residual value.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R9X99A', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-coordinate of the $x$-intercept of the line $2x + 5y = 20$?', NULL, '[{"key":"A","text":"$10$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-10$"},{"key":"D","text":"$20$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The $x$-intercept occurs where $y = 0$, so $2x = 20$ and $x = 10$. Option B results from dividing 20 by the wrong coefficient, 5 instead of 2. Option C results from a sign error when isolating $x$. Option D is the value of $2x$ before dividing by 2 to solve for $x$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U4E10K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store''s revenue increased by $15\\%$ from Year 1 to Year 2, then decreased by $20\\%$ from Year 2 to Year 3. If the revenue in Year 3 was $\\$92{,}000$, what was the revenue in Year 1?', NULL, '[{"key":"A","text":"$\\\\$84{,}640$"},{"key":"B","text":"$\\\\$96{,}842$"},{"key":"C","text":"$\\\\$100{,}000$"},{"key":"D","text":"$\\\\$115{,}000$"}]'::jsonb, 'C', NULL, E'The correct answer is C. Working backward, the Year 2 revenue is $92{,}000 \\div 0.8 = \\$115{,}000$, and the Year 1 revenue is $115{,}000 \\div 1.15 = \\$100{,}000$. Option A ($\\$84{,}640$) results from applying the percent changes forward to $\\$92{,}000$ (multiplying by $1.15$ and then $0.8$) instead of working backward. Option B ($\\$96{,}842$) results from treating the two percent changes as additive (a net $-5\\%$) rather than multiplicative. Option D ($\\$115{,}000$) only reverses the $20\\%$ decrease and stops, without also reversing the $15\\%$ increase.', '{"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U64JWQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $4$ and a height of $10$. What is the total surface area of the cylinder, in terms of $\\pi$?', NULL, '[{"key":"A","text":"$32\\\\pi$"},{"key":"B","text":"$80\\\\pi$"},{"key":"C","text":"$96\\\\pi$"},{"key":"D","text":"$112\\\\pi$"}]'::jsonb, 'D', NULL, E'The correct answer is D. Total surface area is $2\\pi r^2 + 2\\pi rh = 2\\pi(4)^2 + 2\\pi(4)(10) = 32\\pi + 80\\pi = 112\\pi$. Option A ($32\\pi$) accounts only for the two circular bases and omits the lateral surface. Option B ($80\\pi$) accounts only for the lateral surface and omits the two circular bases. Option C ($96\\pi$) results from using $\\pi r^2$ instead of $2\\pi r^2$ for the bases, giving $16\\pi + 80\\pi = 96\\pi$.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}'::jsonb, NULL, 'draft', 1, 85, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UQ0EDQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'Solve for $x$: $\\frac{2x + 1}{3} - \\frac{x - 2}{4} = 1$.', NULL, '[{"key":"A","text":"$\\\\frac{2}{5}$"},{"key":"B","text":"$-\\\\frac{2}{5}$"},{"key":"C","text":"$2$"},{"key":"D","text":"$\\\\frac{14}{5}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Multiply every term by the LCD of 12: $4(2x + 1) - 3(x - 2) = 12$, which expands to $8x + 4 - 3x + 6 = 12$, or $5x + 10 = 12$, so $x = \\frac{2}{5}$. Option B results from a sign error when dividing the final result. Option C comes from failing to distribute the negative sign across $(x - 2)$, treating it as $-3x - 6$ instead of $-3x + 6$, which changes the constant term. Option D results from an arithmetic slip while combining the constant terms after distribution.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VH7HBL', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'For the linear function $f$, $f(3) = 7$ and $f(7) = 19$. What is the rate of change of $f$?', NULL, '[{"key":"A","text":"$3$"},{"key":"B","text":"$12$"},{"key":"C","text":"$\\\\frac{1}{3}$"},{"key":"D","text":"$4$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The rate of change of a linear function equals $\\frac{f(7) - f(3)}{7 - 3} = \\frac{19 - 7}{7 - 3} = \\frac{12}{4} = 3$. Option B is the numerator of the rate-of-change calculation, computed correctly but never divided by the change in $x$. Option C results from a conceptual gap: inverting the ratio to $\\frac{4}{12} = \\frac{1}{3}$. Option D results from an arithmetic slip that divides the correct numerator, 12, by the wrong denominator, 3, instead of 4.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VKTO82', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $ABC$, angle $C$ is the right angle. If $\\sin(A) = \\frac{5}{13}$, what is $\\cos(B)$?', NULL, '[{"key":"A","text":"$\\\\frac{5}{13}$"},{"key":"B","text":"$\\\\frac{5}{12}$"},{"key":"C","text":"$\\\\frac{12}{13}$"},{"key":"D","text":"$\\\\frac{13}{5}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Since angle $C$ is the right angle, angles $A$ and $B$ are complementary ($A + B = 90°$), so $\\cos(B) = \\sin(90° - B) = \\sin(A) = \\frac{5}{13}$. Option C ($\\frac{12}{13}$) is the value of $\\cos(A)$ (found from the Pythagorean identity), which answers for the wrong angle. Option D ($\\frac{13}{5}$) incorrectly takes the reciprocal of $\\sin(A)$, confusing sine with cosecant. Option B ($\\frac{5}{12}$) incorrectly treats the ratio as a tangent value rather than applying the sine-cosine co-function relationship.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WEARO3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A wellness company claims that its new supplement improves sleep quality. In a study, 200 volunteers who had already purchased the supplement online voluntarily completed a self-administered survey rating their sleep quality before and after taking the supplement for one month. Volunteers who completed both surveys reported an average improvement in sleep quality score, and the company concludes that the supplement causes improved sleep quality in the general population. Which of the following most accurately describes a limitation that undermines the company''s causal claim?', NULL, '[{"key":"A","text":"Because the sample was self-selected and there was no control group or random assignment, the observed improvement could result from factors such as placebo effect, natural variation in sleep over time, or dropout of dissatisfied users, rather than the supplement itself."},{"key":"B","text":"A sample of 200 volunteers is too small to detect any meaningful difference in sleep quality scores."},{"key":"C","text":"Because participants took the same survey before and after, the results are automatically biased toward showing improvement due to practice effects with the survey instrument."},{"key":"D","text":"The study cannot be valid because self-reported measures are always too inaccurate to be used in research."}]'::jsonb, 'A', NULL, E'The correct answer is A. Because participants self-selected into the study (they had already purchased and chosen to use the supplement) and there was no randomly assigned control group, the observed before-after improvement is confounded with other explanations, such as placebo effect, regression to the mean, seasonal or lifestyle changes, or dissatisfied users dropping out before completing both surveys, so a causal effect of the supplement cannot be isolated. Option B misapplies a sample-size argument; 200 participants is not inherently too small, and the core problem is the lack of a control group and randomization, not statistical power. Option C identifies one narrow, plausible source of bias but overstates it as the automatic explanation for the entire result, missing the larger design flaw of no control group or random assignment. Option D makes an absolute, overreaching claim that self-report data are always unusable, which is not the central flaw in this particular study''s design.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 115, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WECJ3G', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A linear function $f$ satisfies $f(0) = 4$ and $f(2) = 10$. What is the value of $f(5)$?', NULL, '[{"key":"A","text":"$19$"},{"key":"B","text":"$15$"},{"key":"C","text":"$22$"},{"key":"D","text":"$10$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The rate of change is $\\frac{10 - 4}{2 - 0} = 3$, so $f(x) = 3x + 4$. Then $f(5) = 3(5) + 4 = 19$. Option B results from computing only $3 \\times 5 = 15$ and forgetting to add the initial value of 4. Option C results from an arithmetic slip when extending from $f(2) = 10$ by the wrong number of steps. Option D restates $f(2)$, mistakenly answering for the wrong input value.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 55, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WQN9U6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $h(x) = -3x^4 + 2x^3 - x + 7$ is graphed in the xy-plane. Which of the following describes the end behavior of the graph as $x \\to \\infty$ and as $x \\to -\\infty$?', NULL, '[{"key":"A","text":"As $x \\\\to \\\\infty$, $h(x) \\\\to -\\\\infty$; as $x \\\\to -\\\\infty$, $h(x) \\\\to -\\\\infty$"},{"key":"B","text":"As $x \\\\to \\\\infty$, $h(x) \\\\to \\\\infty$; as $x \\\\to -\\\\infty$, $h(x) \\\\to \\\\infty$"},{"key":"C","text":"As $x \\\\to \\\\infty$, $h(x) \\\\to -\\\\infty$; as $x \\\\to -\\\\infty$, $h(x) \\\\to \\\\infty$"},{"key":"D","text":"As $x \\\\to \\\\infty$, $h(x) \\\\to \\\\infty$; as $x \\\\to -\\\\infty$, $h(x) \\\\to -\\\\infty$"}]'::jsonb, 'A', NULL, E'The correct answer is A. For large $|x|$, the leading term $-3x^4$ dominates the polynomial''s value. Since the degree is even and the leading coefficient is negative, both ends of the graph fall: as $x \\to \\infty$, $h(x) \\to -\\infty$, and as $x \\to -\\infty$, $h(x) \\to -\\infty$ as well, because $x^4$ is positive for both large positive and large negative $x$. Option B ignores the negative sign on the leading coefficient. Options C and D both incorrectly apply odd-degree end behavior (one end up, one end down), which would only be correct if the highest-degree term were odd, such as $x^3$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X3TILC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A factory produces $450$ widgets in $6$ hours. At this same constant rate, how many widgets does the factory produce during a $40$-hour work week?', NULL, '[{"key":"A","text":"$600$"},{"key":"B","text":"$2{,}700$"},{"key":"C","text":"$3{,}000$"},{"key":"D","text":"$3{,}600$"}]'::jsonb, 'C', NULL, E'The correct answer is C. The unit rate is $450 \\div 6 = 75$ widgets per hour, so in a $40$-hour week the factory produces $75 \\times 40 = 3{,}000$ widgets. Option A ($600$) mistakenly applies the rate to an $8$-hour day instead of the $40$-hour week. Option B ($2{,}700$) results from multiplying $450 \\times 6$ instead of first finding the unit rate. Option D ($3{,}600$) results from using $48$ hours instead of $40$ hours in the final multiplication.', '{"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 70, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XMWWG5', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the equation, in slope-intercept form, of the line that passes through the points $(2, 3)$ and $(4, 9)$?', NULL, '[{"key":"A","text":"$y = 3x - 3$"},{"key":"B","text":"$y = -3x - 3$"},{"key":"C","text":"$y = \\\\frac{1}{3}x + 3$"},{"key":"D","text":"$y = 3x + 3$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The slope is $\\frac{9 - 3}{4 - 2} = 3$. Using point-slope form with $(2, 3)$: $y - 3 = 3(x - 2)$, which simplifies to $y = 3x - 3$. Option B results from a sign error that flips the slope to $-3$. Option C results from a conceptual gap: inverting the slope ratio (run over rise) to get $\\frac{1}{3}$ instead of $3$. Option D results from an arithmetic slip when combining $-6 + 3$ to get the constant term.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 80, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YFZIE3', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A store sells notebooks for $\\$3$ each and pens for $\\$2$ each. Maria wants to buy at least 10 items total while spending no more than $\\$24$. If $n$ represents the number of notebooks and $p$ represents the number of pens, which system of inequalities represents this situation?', NULL, '[{"key":"A","text":"$n + p \\\\geq 10$ and $3n + 2p \\\\leq 24$"},{"key":"B","text":"$n + p \\\\leq 10$ and $3n + 2p \\\\geq 24$"},{"key":"C","text":"$n + p \\\\geq 10$ and $2n + 3p \\\\leq 24$"},{"key":"D","text":"$n + p \\\\geq 10$ and $3n + 2p \\\\geq 24$"}]'::jsonb, 'A', NULL, E'The correct answer is A. "At least 10 items total" translates to $n + p \\geq 10$, and "spending no more than $\\$24$" with notebooks at $\\$3$ and pens at $\\$2$ translates to $3n + 2p \\leq 24$. Option B reverses both inequality directions, describing at most 10 items and at least $\\$24$ spent, which contradicts the scenario. Option C swaps the price coefficients, assigning $\\$2$ to notebooks and $\\$3$ to pens instead of the correct prices. Option D correctly represents the item-count inequality but reverses the spending inequality, requiring at least $\\$24$ rather than at most $\\$24$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZB4R0F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally priced at $\\$40$ is on sale for $25\\%$ off. What is the sale price of the shirt?', NULL, '[{"key":"A","text":"$\\\\$10$"},{"key":"B","text":"$\\\\$20$"},{"key":"C","text":"$\\\\$30$"},{"key":"D","text":"$\\\\$50$"}]'::jsonb, 'C', NULL, E'The correct answer is C. A $25\\%$ discount on $\\$40$ is $0.25 \\times 40 = \\$10$, so the sale price is $40 - 10 = \\$30$. Option A ($\\$10$) is only the discount amount, not the final sale price. Option B ($\\$20$) results from mistakenly using $50\\%$ instead of $25\\%$ for the discount. Option D ($\\$50$) results from adding the discount to the price instead of subtracting it.', '{"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 50, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2122NED', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to state the main achievement of Mae Jemison''s career. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'A student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23MNIGI', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the underlined portion of the text so that it conforms to the conventions of Standard English?', E'By the time the researchers published their findings, the original hypothesis ___ multiple times based on new field data.', '[{"key":"A","text":"had been revised"},{"key":"B","text":"was revised"},{"key":"C","text":"has been revised"},{"key":"D","text":"is revised"}]'::jsonb, 'A', NULL, E'The correct answer is A. The phrase "By the time the researchers published their findings" establishes a past event, and the revisions to the hypothesis happened even earlier, before that publication; the past perfect "had been revised" is required to show this action was completed prior to another past action. Option B uses the simple past, which fails to indicate that the revisions occurred before the publishing rather than at the same time. Option C uses the present perfect, which is inconsistent with a sentence entirely set in the past. Option D uses the present tense, which does not fit a sentence describing events that have already concluded.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 85, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25L1LVR', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding would provide the strongest support for the researcher''s hypothesis?', E'A researcher hypothesizes that participants who take a 20-minute nap after learning a new skill will retain the skill better after one week than participants who do not nap. Two groups of volunteers learned an identical typing task; one group napped for 20 minutes immediately afterward, while the other group remained awake and performed an unrelated activity. One week later, both groups were retested on typing speed and accuracy.', '[{"key":"A","text":"The napping group and the non-napping group showed no significant difference in typing accuracy after one week."},{"key":"B","text":"The non-napping group retained typing speed and accuracy better than the napping group after one week."},{"key":"C","text":"The napping group retained typing speed and accuracy significantly better than the non-napping group after one week."},{"key":"D","text":"Both groups reported feeling equally confident about their typing ability before the retest."}]'::jsonb, 'C', NULL, E'The correct answer is C. The hypothesis predicts that napping improves retention of the typing skill, so a significant retention advantage for the napping group directly supports it. Option A describes a null result, which would not support the hypothesis. Option B reports the opposite pattern, contradicting the hypothesis. Option D measures self-reported confidence rather than actual retention of typing speed and accuracy, so it does not bear on the claim being tested.', '{"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27K5SK2', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'When a honeybee scout finds a rich source of nectar, it returns to the hive and performs a waggle dance. The dance''s specific movements encode the direction and distance to the food source relative to the sun''s position. Other worker bees observe the dance and use the encoded information to fly directly to the nectar, allowing the colony to exploit food sources efficiently without each bee needing to search independently.', '[{"key":"A","text":"Honeybees communicate the location of food sources to other bees through a specialized dance."},{"key":"B","text":"Honeybee scouts compete with worker bees to determine which nectar source is richest."},{"key":"C","text":"The waggle dance allows bees to regulate the hive''s internal temperature."},{"key":"D","text":"Worker bees rely only on the sun''s position, without any information from other bees, to locate food."}]'::jsonb, 'A', NULL, E'The correct answer is A. The text centrally describes how the waggle dance encodes direction and distance so other bees can find nectar without searching independently. Option B misreads the text as describing competition, which is never mentioned. Option C swaps the dance''s actual function (location information) for an unrelated concept, temperature regulation. Option D captures only the sun-position detail while ignoring the dance itself, contradicting the passage''s statement that bees use the encoded dance information rather than the sun alone.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 70, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28KX00T', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to emphasize a contrast between two irrigation methods. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'A student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29C3UBI', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the function of the sentence "New lanes tend to attract new drivers who previously avoided the route" in the passage?', E'Urban planners have long assumed that adding more traffic lanes reduces congestion. Yet data from a dozen major cities that expanded highways over the past twenty years show congestion levels returning to, or exceeding, pre-expansion levels within just a few years. New lanes tend to attract new drivers who previously avoided the route, a phenomenon researchers call induced demand. Rather than solving congestion, then, highway expansion may simply postpone it while consuming vast public resources.', '[{"key":"A","text":"it introduces a counterargument that the author will later refute"},{"key":"B","text":"it offers a mechanism that explains the surprising data described earlier"},{"key":"C","text":"it summarizes the passage''s main claim before restating it"},{"key":"D","text":"it presents an exception to the pattern found in the twelve cities"}]'::jsonb, 'B', NULL, E'The correct answer is B. The sentence names "induced demand" as the mechanism that explains why congestion returned despite new lanes, directly accounting for the surprising data cited just before it. Option A is wrong because the sentence is never treated as an opposing view to be refuted; it supports the author''s point. Option C is incorrect because the sentence introduces new explanatory information rather than repeating an already-stated claim. Option D misreads the sentence as describing an exception, when it actually explains the pattern common to all twelve cities.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 85, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AN7BMA', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the underlined portion of the text so that it conforms to the conventions of Standard English?', E'Although the committee reviewed dozens of proposals___ only one design met every safety requirement outlined in the building code.', '[{"key":"A","text":", only one design"},{"key":"B","text":"; only one design"},{"key":"C","text":" only one design"},{"key":"D","text":". Only one design"}]'::jsonb, 'A', NULL, E'The correct answer is A. "Although the committee reviewed dozens of proposals" is a dependent clause, and a comma is required to separate it from the independent clause that follows. Option B is incorrect because a semicolon can only join two independent clauses, and "Although the committee reviewed dozens of proposals" cannot stand alone as a sentence. Option C omits the required comma after the introductory dependent clause, producing a boundary error. Option D incorrectly places a period after the dependent clause, turning it into a sentence fragment.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 85, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ARAXW7', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the main purpose of the passage?', E'Hummingbirds are the only birds capable of sustained backward flight. Unlike most birds, whose wings move in a simple up-and-down motion, hummingbirds rotate their wings at the shoulder in a figure-eight pattern. This unique motion generates lift on both the upstroke and the downstroke, allowing the birds to hover in place, dart sideways, and even fly in reverse when retreating from a flower.', '[{"key":"A","text":"to argue that hummingbirds are more skilled fliers than other birds"},{"key":"B","text":"to explain the wing motion that enables hummingbirds'' unusual flight abilities"},{"key":"C","text":"to describe the anatomical differences between hummingbirds and other bird species in general"},{"key":"D","text":"to criticize inaccurate popular beliefs about hummingbird flight"}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage focuses on describing the figure-eight wing motion and how it produces lift on both strokes, directly explaining the mechanism behind hummingbirds'' unusual flight abilities. Option A treats the passage as an argument ranking skill, but the passage never compares overall flying skill, only wing mechanics. Option C overstates the scope, since the passage discusses only wing motion, not general anatomy. Option D is unsupported because the passage never references or corrects any popular misconception.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 70, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BXIP5T', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Historians have long debated whether the printing press caused the Reformation or merely accelerated a movement already underway. Proponents of the causal view point to the rapid, wide circulation of Luther''s theses. Skeptics counter that regional oral networks and existing anticlerical sentiment had spread reformist ideas for decades before Gutenberg''s technology reached full scale. The most recent scholarship suggests a synthesis: the press did not originate reform but dramatically compressed the time between an idea''s articulation and its widespread adoption, transforming a slow-moving current into a rapid tide.', '[{"key":"A","text":"The printing press single-handedly caused the Protestant Reformation."},{"key":"B","text":"Scholars now generally agree that the printing press sped up an already-developing reform movement rather than originating it."},{"key":"C","text":"Oral networks were entirely responsible for the spread of reformist ideas, with the printing press playing no meaningful role."},{"key":"D","text":"Historians have abandoned the debate over the printing press''s role in the Reformation."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage''s central point is the synthesis view: the press did not originate reform but compressed the timeline of its spread. Option A misreads this synthesis as a purely causal claim, which the text explicitly rejects. Option C misreads the synthesis in the opposite direction, denying the press any role despite the text crediting it with dramatically compressing adoption time. Option D overreaches by inferring that presenting a scholarly synthesis means the debate itself has been abandoned, which the text never states.', '{"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 115, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C5OWQO', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which piece of evidence would most directly weaken the economists'' argument?', E'Economists studying a regional minimum-wage increase argued that the policy would reduce youth employment, particularly in retail. To evaluate this claim, they compared employment data from the affected region against a neighboring region with no wage increase, examining only workers aged 16 to 19 in retail positions over the two years following implementation, since youth retail workers occupy the entry-level positions most sensitive to labor-cost changes.', '[{"key":"A","text":"Youth retail employment in the affected region declined by 8 percent while it rose by 1 percent in the neighboring region over the same period."},{"key":"B","text":"Youth retail employment in the affected region and the neighboring region both grew by roughly 4 percent over the two-year period."},{"key":"C","text":"Overall retail employment, including all age groups, declined slightly in the affected region."},{"key":"D","text":"The affected region''s minimum wage increase was larger than increases in most other states that year."}]'::jsonb, 'B', NULL, E'The correct answer is B. The economists argue the wage increase reduced youth retail employment; if youth retail employment grew at a similar rate in both the affected and unaffected regions, that parallel growth undercuts the claim that the policy caused a reduction. Option A shows exactly the divergence the economists predicted, which would support rather than weaken their argument. Option C shifts to overall retail employment across all ages, a different population than the youth workers the argument specifically concerns. Option D describes the policy''s magnitude but says nothing about the employment outcome, so it does not bear on the argument''s evidentiary claim.', '{"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}'::jsonb, NULL, 'draft', 1, 115, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EFS1D3', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to explain why the 1918 discovery was initially dismissed by other scientists, while also noting the long-term significance of the finding. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'A student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H7EGLW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the underlined portion of the text so that it conforms to the conventions of Standard English?', E'The museum''s new exhibit features rare fossils from the Jurassic period___ visitors can see a full-sized dinosaur skeleton reconstructed from real bone fragments.', '[{"key":"A","text":"; visitors"},{"key":"B","text":", visitors"},{"key":"C","text":" visitors"},{"key":"D","text":"; and visitors"}]'::jsonb, 'A', NULL, E'The correct answer is A. Both "The museum''s new exhibit features rare fossils from the Jurassic period" and "visitors can see a full-sized dinosaur skeleton reconstructed from real bone fragments" are independent clauses, so a semicolon is the correct way to join them without a coordinating conjunction. Option B creates a comma splice, joining two independent clauses with only a comma. Option C creates a run-on sentence with no punctuation at all between the two clauses. Option D misuses the semicolon by pairing it with the coordinating conjunction "and"; a semicolon used to join independent clauses should not be followed by a coordinating conjunction.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 70, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J38Y48', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "tempered" most nearly means', E'Despite record profits reported by three of the sector''s largest firms, the economist tempered her optimism about the industry''s broader recovery, noting that smaller firms without such firms'' capital reserves continued to report declining revenue. She cautioned that a recovery driven by a handful of dominant players could mask deeper structural weaknesses rather than signal genuine, sector-wide stability.', '[{"key":"A","text":"hardened"},{"key":"B","text":"moderated"},{"key":"C","text":"eliminated"},{"key":"D","text":"intensified"}]'::jsonb, 'B', NULL, E'The correct answer is B. The economist still holds some optimism but qualifies it in light of struggling smaller firms, which matches "moderated." Option A, "hardened," borrows a literal sense of temper (as in tempering metal) that does not fit the context of qualifying an opinion. Option C, "eliminated," overstates the passage, which shows the economist tempering, not abandoning, her optimism. Option D, "intensified," is the opposite of the cautious qualification described.', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J4Y362', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the student''s claim?', E'A student claims that plants grown in a room with a north-facing window will grow taller than plants grown in a room with a south-facing window, due to differences in light angle throughout the day. To test this claim, the student places ten seedlings in each room and measures their height in centimeters at the end of four weeks under identical watering and soil conditions.', '[{"key":"A","text":"Seedlings in the south-facing room averaged 22 cm in height after four weeks, compared to 15 cm for the north-facing room."},{"key":"B","text":"Seedlings in the north-facing room averaged 22 cm in height after four weeks, compared to 15 cm for the south-facing room."},{"key":"C","text":"Both rooms received identical amounts of water throughout the four-week period."},{"key":"D","text":"The soil in both rooms was tested and found to have the same nutrient content."}]'::jsonb, 'B', NULL, E'The correct answer is B. The student''s claim is that north-facing seedlings grow taller, so a finding showing greater average height in the north-facing room directly supports it. Option A reports the opposite result, which would undermine rather than support the claim. Options C and D describe controlled variables (water and soil) that were already held constant by design; confirming they were equal does not provide evidence about the height outcome the claim concerns.', '{"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}'::jsonb, NULL, 'draft', 1, 70, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M25U6E', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "meticulous" most nearly means', E'The laboratory director praised Elena for her meticulous approach to data collection. Every measurement was recorded twice, every instrument recalibrated before use, and every anomaly investigated rather than dismissed. Colleagues who worked more quickly sometimes overlooked small inconsistencies that later proved significant, but Elena''s careful, methodical habits meant her results rarely required correction.', '[{"key":"A","text":"careless"},{"key":"B","text":"painstaking"},{"key":"C","text":"hurried"},{"key":"D","text":"indifferent"}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage describes Elena double-checking measurements, recalibrating instruments, and investigating every anomaly, all of which illustrate a painstaking, highly careful approach. Option A, "careless," is the opposite of the behavior described. Option C, "hurried," contradicts the passage''s emphasis on double-checking and thoroughness. Option D, "indifferent," misrepresents Elena''s evident engagement with her work.', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}'::jsonb, NULL, 'draft', 1, 70, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NN2CTK', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best characterizes the relationship between Reyes''s and Ruiz''s arguments?', E'Text 1: Economist Dana Reyes maintains that rising automation in manufacturing will ultimately raise wages for remaining workers, since automation increases each worker''s output and firms competing for a shrinking pool of skilled labor must offer higher pay to retain them.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P8SGZC', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the underlined portion of the text so that it conforms to the conventions of Standard English?', E'The lab''s protocol includes___ calibrating the equipment, recording baseline data, and cross-checking results against the control group.', '[{"key":"A","text":"includes:"},{"key":"B","text":"includes,"},{"key":"C","text":"includes"},{"key":"D","text":"includes;"}]'::jsonb, 'C', NULL, E'The correct answer is C. "Includes" is a transitive verb directly followed by its object, a list of gerund phrases; no punctuation should separate a verb from the object it takes, so the list follows "includes" with no mark at all. Option A is incorrect because a colon must follow a complete independent clause, and "The lab''s protocol includes" is not complete without its object—the colon here improperly interrupts the verb and its object. Option B inserts an unnecessary comma between the verb and its direct object. Option D is incorrect because a semicolon must join two independent clauses, and neither side of "includes;" forms one here.', '{"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 115, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PFDBRM', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Early researchers assumed that octopuses relied almost entirely on chemical cues to identify prey hidden in sand. Later experiments showed that octopuses could distinguish prey shapes using vision alone, even when chemical cues were blocked. ______ subsequent studies revealed that some octopuses could learn to solve puzzles through observation of other octopuses, a capacity once thought unique to vertebrates with complex social structures.', '[{"key":"A","text":"Consequently,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"In other words,"}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage builds a cumulative case that octopuses possess more sophisticated cognitive abilities than once believed, and the final sentence adds a further, escalating example (social learning) to the earlier example (vision-based prey detection), so an additive transition is needed. Option A is wrong because "Consequently" implies the social-learning finding resulted from the vision finding, but the two discoveries are independent pieces of evidence, not cause and effect. Option C is wrong because "Nevertheless" signals contrast with the prior sentence, but the social-learning finding supports the same overall claim rather than opposing it. Option D is wrong because "In other words" signals a restatement of the same idea, but the social-learning finding is a distinct, additional discovery, not a rephrasing of the vision finding.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PFU62R', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most reasonably explains why revenue grew far less than sales volume?', E'A small bakery reduced the price of its signature loaf by 15 percent while simultaneously increasing its advertising budget. In the three months following these changes, weekly sales volume rose by 40 percent, but total weekly revenue increased by only 6 percent compared to the same period the previous year.', '[{"key":"A","text":"The lower per-loaf price meant each additional loaf sold contributed less revenue than before, offsetting most of the volume gain."},{"key":"B","text":"The bakery''s advertising budget increase eliminated any profit from the additional loaves sold."},{"key":"C","text":"Customers began purchasing fewer loaves per visit despite the price reduction."},{"key":"D","text":"The bakery raised prices on other products to compensate for the loaf discount."}]'::jsonb, 'A', NULL, E'The correct answer is A. Because each loaf now sells for 15 percent less, the 40 percent rise in units sold translates into a much smaller revenue increase, which follows logically from the stated price cut and volume figures. Option B introduces profit and advertising costs, concepts the text never quantifies or connects to the revenue figure. Option C contradicts the stated 40 percent increase in sales volume. Option D invents a pricing change on other products that the text never mentions.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PG353E', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall structure of the passage?', E'It is tempting to credit the twentieth century''s rise in life expectancy entirely to medical breakthroughs such as antibiotics and vaccines. Yet demographic historians point out that most of the decline in mortality occurred before these interventions became widespread, driven instead by improvements in sanitation, clean water infrastructure, and nutrition. This is not to diminish medicine''s later contributions, but to correct a chronology that flatters twentieth-century science while overlooking the quieter, earlier work of engineers and public health reformers.', '[{"key":"A","text":"it presents a popular assumption, then complicates it with historical evidence before offering a qualified conclusion"},{"key":"B","text":"it introduces two competing theories and endorses the one supported by more recent data"},{"key":"C","text":"it describes a historical event chronologically and then predicts future trends"},{"key":"D","text":"it refutes a claim entirely and replaces it with an opposing claim with no qualification"}]'::jsonb, 'A', NULL, E'The correct answer is A. The passage opens with the popular assumption that medicine alone explains rising life expectancy, complicates it with historians'' evidence about sanitation and nutrition, and closes with a qualified conclusion that explicitly avoids dismissing medicine''s contribution. Option B mischaracterizes the passage as framing two competing theories rather than a popular assumption being corrected by evidence. Option C is incorrect because the passage does not narrate events chronologically or make any prediction about the future. Option D is wrong because the final sentence explicitly qualifies the correction ("This is not to diminish medicine''s later contributions"), so the claim is not refuted without qualification.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QEABS7', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the two texts, how would Dr. Chen most likely respond to Dr. Alvarez''s argument?', E'Text 1: Dr. Alvarez argues that vertical farming will be essential to feeding growing urban populations. By stacking crops in climate-controlled indoor towers, cities can produce vegetables year-round using a fraction of the water required by traditional agriculture, all without the land, weather, or pest challenges that outdoor farms face.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QSFCCP', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice can most reasonably be inferred from the text?', E'In a controlled study, researchers found that a species of deep-sea fish exhibited bioluminescent flashing patterns that varied depending on the presence of predators versus potential mates nearby. When predators were detected, flashes were brief and irregular; when potential mates were nearby, flashes followed a longer, rhythmic sequence. Notably, fish raised in isolation from birth, with no exposure to either predators or other fish, still produced both distinct flashing patterns when first exposed to each stimulus.', '[{"key":"A","text":"The bioluminescent flashing patterns are largely innate rather than learned through social experience."},{"key":"B","text":"Isolated fish are incapable of producing rhythmic flashing sequences."},{"key":"C","text":"Fish exposed to predators from birth develop more complex flashing patterns than fish raised with mates."},{"key":"D","text":"The flashing patterns serve no purpose other than avoiding predators."}]'::jsonb, 'A', NULL, E'The correct answer is A. Because isolated fish with no prior exposure to predators or other fish still produced both correct flashing patterns on first exposure, the patterns must be present from birth rather than learned socially, supporting an innate origin. Option B directly contradicts the text, which states isolated fish did produce the rhythmic sequence. Option C invents a comparison of pattern complexity across rearing conditions that the text never makes. Option D overreaches by ignoring the mate-attraction function the text explicitly describes alongside predator avoidance.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 115, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R1WWD0', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, which of the following is a detail explicitly stated about the survey''s findings?', E'A recent municipal survey found that neighborhoods with tree canopy coverage above 30 percent recorded average summer surface temperatures nearly 5 degrees Fahrenheit lower than neighborhoods with less than 10 percent coverage. The survey''s authors noted that canopy coverage correlated with, but did not fully explain, differences in cooling: building materials, street width, and proximity to water also contributed to temperature variation across the studied neighborhoods.', '[{"key":"A","text":"Tree canopy coverage was the only factor found to influence neighborhood temperature."},{"key":"B","text":"Neighborhoods with more tree canopy had lower average summer surface temperatures than those with less."},{"key":"C","text":"Building materials had a greater effect on temperature than tree canopy coverage did."},{"key":"D","text":"The survey concluded that street width alone accounts for most temperature differences."}]'::jsonb, 'B', NULL, E'The correct answer is B. The text explicitly states that higher-canopy neighborhoods recorded temperatures nearly 5 degrees lower than lower-canopy neighborhoods. Option A misreads the passage, which explicitly says canopy coverage did not fully explain the differences. Option C takes the mentioned factor of building materials and overstates its relative effect, which the text never compares. Option D isolates one contributing factor, street width, and misreads it as the primary explanation, when the text lists it only as one of several contributors.', '{"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TNZB6K', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes how Nair''s argument relates to Webb''s?', E'Text 1: Historian Marcus Webb argues that the collapse of the medieval trade network was driven primarily by the plague''s decimation of skilled artisans and merchants. With so few tradespeople left to produce and transport goods, the intricate web of exchange that had linked cities for centuries unraveled within a single generation.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UAQU70', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'A city planner proposed replacing a downtown parking lot with a public park. Supporters argued that green space would draw more foot traffic to nearby shops. ______ several business owners worried that removing the lot would drive away customers who rely on convenient parking.', '[{"key":"A","text":"As a result,"},{"key":"B","text":"In fact,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"In addition,"}]'::jsonb, 'C', NULL, E'The correct answer is C. The first sentence presents support for the park proposal, while the second presents opposing concerns from business owners, so a contrast transition is required. Option A is wrong because "As a result" implies the business owners'' worry is a consequence of the supporters'' argument, which misstates the relationship as causal rather than oppositional. Option B is wrong because "In fact" signals confirmation or elaboration of the same point, not a shift to an opposing view. Option D is wrong because "In addition" signals that the second sentence adds a similar supporting point, but it introduces a conflicting concern instead.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 85, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UF34OD', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marcus spent months practicing his violin for the regional competition. ______ he placed only fourth, his teacher praised the noticeable improvement in his tone and rhythm.', '[{"key":"A","text":"Although"},{"key":"B","text":"Therefore,"},{"key":"C","text":"For example,"},{"key":"D","text":"Similarly,"}]'::jsonb, 'A', NULL, E'The correct answer is A. The second sentence describes praise despite a disappointing placement, so a contrast word is needed to link the modest result with the positive feedback. Option B is wrong because "Therefore" signals a cause-effect relationship, but praise is not a result of placing fourth. Option C is wrong because the second sentence is not an example of the first. Option D is wrong because "Similarly" signals agreement between ideas, but the sentences present a contrast, not a similarity.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}'::jsonb, NULL, 'draft', 1, 65, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W22ZAA', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Based on the text, what can most reasonably be inferred about Maria?', E'Maria packed an umbrella, a raincoat, and waterproof boots before leaving for her weekend hiking trip. She checked the weather forecast twice the night before and again just before loading her car.', '[{"key":"A","text":"Maria expects rainy weather during her hiking trip."},{"key":"B","text":"Maria forgot to check the weather forecast before her trip."},{"key":"C","text":"Maria dislikes hiking and only goes because of pressure from friends."},{"key":"D","text":"Maria plans to cancel her trip due to the weather."}]'::jsonb, 'A', NULL, E'The correct answer is A. Packing rain gear and repeatedly checking the forecast reasonably imply that Maria anticipates rain. Option B directly contradicts the text, which states she checked the forecast three times. Option C introduces a claim about Maria''s feelings toward hiking that the text gives no basis for. Option D overreaches beyond the evidence; packing gear for a trip suggests she intends to go, not cancel it.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 70, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WDQR2M', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "specious" most nearly means', E'The appellate court''s decision hinged on a single clause, and the judge acknowledged that a specious reading of the contract''s language might allow either party to claim victory. Only by tracing the clause back to the original negotiation records, she wrote, could one determine which interpretation the two companies had actually intended when the agreement was signed.', '[{"key":"A","text":"thorough"},{"key":"B","text":"plausible but false"},{"key":"C","text":"deliberately vague"},{"key":"D","text":"legally binding"}]'::jsonb, 'B', NULL, E'The correct answer is B. The judge notes that a reading that seems to support either party''s claim could still be wrong, which is precisely what "specious" (seemingly plausible but actually false) captures; only the negotiation records can settle the true intent. Option A, "thorough," is unrelated to the misleading quality being described. Option C, "deliberately vague," mischaracterizes the clause as intentionally unclear rather than as an interpretation that misleads while appearing sound. Option D, "legally binding," describes contract enforceability, not the deceptive plausibility the word conveys here.', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XARLYW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the underlined portion of the text so that it conforms to the conventions of Standard English?', E'The research team traveled to three sites to collect samples: Bora Bora, French Polynesia; Key West, Florida___ and Cairns, Australia.', '[{"key":"A","text":"; and"},{"key":"B","text":", and"},{"key":"C","text":": and"},{"key":"D","text":" and"}]'::jsonb, 'A', NULL, E'The correct answer is A. Because each item in this series already contains an internal comma ("Bora Bora, French Polynesia"), a semicolon is required to separate the items in the list clearly, including before the final "and." Option B uses only a comma, which is insufficient once list items contain their own internal commas and creates ambiguity about how many items are in the series. Option C incorrectly introduces a colon mid-series, and a colon cannot be used to separate items within an already-introduced list. Option D omits punctuation entirely before "and," leaving the boundary between the second and third items unclear.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y02CGR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the underlined portion of the text so that it conforms to the conventions of Standard English?', E'___ the data for inconsistencies for several days, the analyst finally realized that the anomaly was caused by a faulty sensor rather than by a genuine change in trend.', '[{"key":"A","text":"Having checked"},{"key":"B","text":"Having been checked"},{"key":"C","text":"To have checked"},{"key":"D","text":"Have checked"}]'::jsonb, 'A', NULL, E'The correct answer is A. The opening modifier must logically describe "the analyst," who performed the checking; the active participial phrase "Having checked" correctly shows the analyst completed this action before realizing the cause of the anomaly. Option B uses a passive participial phrase, which illogically implies that the analyst was the one being checked rather than the one doing the checking, creating a dangling modifier. Option C uses an infinitive form that does not function as a logical modifier for the subject and misstates the relationship between the two actions. Option D uses a finite present-perfect verb form, which cannot grammatically function as a sentence-opening modifying phrase and produces an ungrammatical fragment.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 115, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YUR3ON', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the underlined portion of the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts ___ housed in a climate-controlled vault beneath the library.', '[{"key":"A","text":"is"},{"key":"B","text":"are"},{"key":"C","text":"were"},{"key":"D","text":"being"}]'::jsonb, 'A', NULL, E'The correct answer is A. The subject of the sentence is the singular noun "collection," not "manuscripts," which is the object of the prepositional phrase "of rare manuscripts"; a singular subject requires the singular verb "is." Option B incorrectly agrees with the plural object of the preposition rather than the singular subject. Option C repeats this agreement error and also shifts to the past tense without any signal in the sentence that a past tense is needed. Option D is not a finite verb and cannot serve as the sentence''s main verb, leaving the sentence without a complete predicate.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 70, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z93DFP', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "galvanized" most nearly means', E'When the city council proposed replacing the historic library with a parking structure, the announcement galvanized residents who had previously shown little interest in local politics. Petitions circulated within days, and dozens of citizens who had never before attended a public meeting packed the council chambers to voice their objections. The proposal, intended to be a routine procedural matter, instead became the most contested issue the council had faced in years.', '[{"key":"A","text":"exhausted"},{"key":"B","text":"confused"},{"key":"C","text":"energized"},{"key":"D","text":"discouraged"}]'::jsonb, 'C', NULL, E'The correct answer is C. The passage shows residents suddenly circulating petitions and packing council meetings, behavior consistent with being energized into action. Option A, "exhausted," contradicts the surge of new activity described. Option B, "confused," is not supported by the residents'' clear, purposeful response. Option D, "discouraged," is the opposite of the mobilized reaction the passage describes.', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}'::jsonb, NULL, 'draft', 1, 85, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-08"}'::jsonb, '{"model":"claude","generation_date":"2026-07-08","prompt_version":"questions_governance_v1"}'::jsonb);
